INSERT INTO INT_SERVERFUNCTION (ID, NAME, DESCRIPTION, TYPE, CODE, JDBC_ID, PUBLIC_EXECUTION, CRON_EXPRESSION, CRON_INPUT_JSON, CREATED_BY) VALUES (122, 'hotPremissasBase', 'Premissas: CICLOS+CONTAS em 1 ida.', 'SQL', 'SELECT
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',ID,''NOME'',NOME,''ANO'',ANO,''STATUS'',STATUS,''ULTIMO_MES_REALIZADO'',ULTIMO_MES_REALIZADO,''VERSAO_ATUAL'',VERSAO_ATUAL,''VERSAO_CONTROLE'',VERSAO_CONTROLE,''VERSAO_ORIGEM_ID'',VERSAO_ORIGEM_ID,''CRIADO_EM'',CRIADO_EM,''CRIADO_POR'',CRIADO_POR)) FROM CICLO), JSON_ARRAY()) AS CICLOS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',ID,''CODIGO'',CODIGO,''NOME'',NOME)) FROM CONTA_CONTABIL), JSON_ARRAY()) AS CONTAS', NULL, FALSE, NULL, NULL, 'sarah@mitralab.io');
